<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('teacher','admin');$eid=get_int('exam_id');$s=db()->prepare('SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?');$s->execute([$eid]);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد.');$s=db()->prepare('SELECT a.*,u.full_name,u.mobile FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.exam_id=? ORDER BY a.score DESC');$s->execute([$eid]);$rows=$s->fetchAll();$scores=array_map(fn($x)=>(float)($x['score']??0),$rows);$avg=$scores?array_sum($scores)/count($scores):0;$max=$scores?max($scores):0;$min=$scores?min($scores):0;$title='نتایج آزمون';require __DIR__.'/../partials/header.php';?><h1>نتایج: <?=e($exam['title'])?></h1><p class="muted"><?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?></p><div class="grid grid-3"><div class="card stat"><span>تعداد پاسخ‌ها</span><strong><?=count($rows)?></strong></div><div class="card stat"><span>میانگین نمره</span><strong><?=format_score($avg)?></strong></div><div class="card stat"><span>بیشینه / کمینه</span><strong><?=format_score($max)?> / <?=format_score($min)?></strong></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>دانش‌آموز</th><th>موبایل</th><th>وضعیت</th><th>نمره</th><th>درصد</th><th>ثبت</th><th>داوری</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['mobile'])?></td><td><?=e($r['status'])?></td><td><?=format_score($r['score'])?></td><td><?=format_score($r['percentage'])?>%</td><td><?=e($r['submitted_at'])?></td><td><a class="btn btn-sm btn-primary" href="<?=e(url('teacher/grade.php?attempt_id='.$r['id']))?>">داوری تشریحی</a></td></tr><?php endforeach;?></tbody></table></div><a class="btn btn-light" href="<?=e(url('teacher/index.php'))?>">بازگشت</a><?php require __DIR__.'/../partials/footer.php'; ?>
